-- Historical schema from SiteBrush 9d4a3ab9c1c4b152e1ddd520b305921fb22ac5cc (25 commits before the updater base).
CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,domain TEXT,email TEXT,password TEXT,is_admin INTEGER,UNIQUE(domain,email));
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_email TEXT,created_at TEXT,admin_ip_trust INTEGER NOT NULL DEFAULT 1, client_ip TEXT NOT NULL DEFAULT '', user_agent TEXT NOT NULL DEFAULT '', language TEXT NOT NULL DEFAULT 'en', security_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE pages(domain TEXT,path TEXT,title TEXT,html TEXT,published INTEGER,PRIMARY KEY(domain,path));
CREATE TABLE published_pages(domain TEXT,path TEXT,title TEXT,html TEXT,PRIMARY KEY(domain,path));
CREATE TABLE page_redirects(domain TEXT,old_path TEXT,new_path TEXT,created_at TEXT,PRIMARY KEY(domain,old_path));
CREATE TABLE domain_storage_usage(domain TEXT PRIMARY KEY,page_bytes INTEGER DEFAULT 0,published_page_bytes INTEGER DEFAULT 0,revision_bytes INTEGER DEFAULT 0,file_bytes INTEGER DEFAULT 0,published_static_bytes INTEGER DEFAULT 0,limit_bytes INTEGER DEFAULT 10737418240,updated_at TEXT, import_queue_bytes INTEGER DEFAULT 0);
CREATE TABLE auth_ip_failures(domain TEXT,client_ip TEXT,failure_count INTEGER DEFAULT 0,blocked_until TEXT,hard_locked INTEGER DEFAULT 0,last_failed_at TEXT,last_attempt_at TEXT,PRIMARY KEY(domain,client_ip));
CREATE TABLE revisions(id INTEGER PRIMARY KEY AUTOINCREMENT,domain TEXT,page_path TEXT,html TEXT,created_at TEXT,is_active INTEGER DEFAULT 1);
CREATE TABLE domain_aliases(primary_domain TEXT,alias_domain TEXT UNIQUE,verification_token TEXT,is_verified INTEGER DEFAULT 0,dns_a_ok INTEGER DEFAULT 0,is_selected INTEGER DEFAULT 0,last_checked_at TEXT);
CREATE TABLE analytics_configuration(domain TEXT PRIMARY KEY,goals TEXT NOT NULL);
CREATE TABLE domain_states(domain TEXT PRIMARY KEY,is_frozen INTEGER DEFAULT 0);
CREATE TABLE domain_ssl_settings(domain TEXT PRIMARY KEY,auto_ssl_enabled INTEGER DEFAULT 0,manually_disabled INTEGER DEFAULT 0,last_checked_at TEXT,last_failed_at TEXT,last_failure_reason TEXT,retry_after TEXT,certificate_expires_at TEXT,last_acme_attempt_at TEXT,last_acme_success_at TEXT,certificate_last_validated_at TEXT);
CREATE TABLE page_password_rules(domain TEXT,path TEXT,password_hash TEXT,created_at TEXT,updated_at TEXT,PRIMARY KEY(domain,path));
CREATE TABLE page_password_sessions(token TEXT PRIMARY KEY,domain TEXT,path TEXT,created_at TEXT);
CREATE TABLE domain_chroot_locations(domain TEXT,url_path TEXT,directory_path TEXT,updated_at TEXT,PRIMARY KEY(domain,url_path));
CREATE TABLE domain_backup_tokens(domain TEXT PRIMARY KEY,token TEXT,updated_at TEXT);
CREATE TABLE admin_stealth_modes(domain TEXT,email TEXT,enabled_at INTEGER NOT NULL,PRIMARY KEY(domain,email));
CREATE TABLE file_access_rules(domain TEXT,file_name TEXT,access_mode TEXT,token TEXT,expires_at TEXT,single_use_left INTEGER DEFAULT 0,token_use_count INTEGER DEFAULT 0,PRIMARY KEY(domain,file_name));
CREATE TABLE file_metadata(domain TEXT,file_name TEXT,page_path TEXT,size INTEGER,mime_type TEXT,created_at TEXT,updated_at TEXT,source TEXT,download_count INTEGER DEFAULT 0,PRIMARY KEY(domain,file_name));
CREATE TABLE email_confirmations(token TEXT PRIMARY KEY,domain TEXT,action TEXT,email TEXT,password TEXT,verification_code TEXT,current_email TEXT,return_path TEXT,language_code TEXT,created_at TEXT,expires_at TEXT, attempts INTEGER NOT NULL DEFAULT 0, request_ip TEXT);
CREATE TABLE analytics_events(id INTEGER PRIMARY KEY AUTOINCREMENT,domain TEXT,path TEXT,query TEXT,method TEXT,status_code INTEGER,content_source TEXT,occurred_at TEXT,duration_ms INTEGER,client_ip TEXT,remote_addr TEXT,user_agent TEXT,referer TEXT,accept_language TEXT,geo_country_code TEXT,geo_city TEXT,geo_latitude REAL DEFAULT 0,geo_longitude REAL DEFAULT 0,geo_source TEXT,visitor_id TEXT,is_admin INTEGER DEFAULT 0,is_asset INTEGER DEFAULT 0,is_controller INTEGER DEFAULT 0);
CREATE TABLE analytics_reports(domain TEXT PRIMARY KEY,generated_at TEXT,period_start TEXT,period_end TEXT,event_count INTEGER,report_json TEXT);
CREATE TABLE sitebrush_migrations(name TEXT PRIMARY KEY,applied_at INTEGER NOT NULL);
CREATE TABLE whole_site_imports(import_id TEXT PRIMARY KEY,domain TEXT NOT NULL,page_path TEXT NOT NULL,source_url TEXT NOT NULL,auto_templates INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'partial',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE whole_site_import_pages(import_id TEXT NOT NULL,domain TEXT NOT NULL,page_key TEXT NOT NULL,page_url TEXT NOT NULL,local_path TEXT NOT NULL,link_offset INTEGER NOT NULL DEFAULT 0,storage_bytes INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL,PRIMARY KEY(import_id,page_key));
CREATE TABLE account_trusted_ips(domain TEXT,email TEXT,client_ip TEXT,confirmed_at INTEGER,last_login INTEGER,PRIMARY KEY(domain,email,client_ip));
CREATE TABLE admin_allowed_ips(domain TEXT,email TEXT,client_ip TEXT,added_at INTEGER,PRIMARY KEY(domain,email,client_ip));
CREATE TABLE admin_ip_policies(domain TEXT,email TEXT,enabled_at INTEGER,PRIMARY KEY(domain,email));
CREATE TABLE account_session_ips(session_token TEXT,domain TEXT,email TEXT,client_ip TEXT,used_at INTEGER,PRIMARY KEY(domain,email,client_ip));
CREATE TABLE account_login_codes(token TEXT PRIMARY KEY,domain TEXT,email TEXT,client_ip TEXT,code_hash TEXT,password_hash TEXT,created_at INTEGER,attempts INTEGER,return_path TEXT,language TEXT);
CREATE TABLE account_code_rates(domain TEXT,email TEXT,client_ip TEXT,window_start INTEGER,last_sent INTEGER,sent_count INTEGER,PRIMARY KEY(domain,email,client_ip));
CREATE TABLE account_passkeys(domain TEXT,email TEXT,user_handle TEXT,credential_id TEXT,credential_json TEXT,created_at INTEGER,last_used_at INTEGER,PRIMARY KEY(domain,credential_id));
CREATE TABLE account_webauthn_challenges(token TEXT PRIMARY KEY,domain TEXT,email TEXT,kind TEXT,session_json TEXT,client_ip TEXT,return_path TEXT,created_at INTEGER);
CREATE TABLE account_totp(domain TEXT,email TEXT,secret TEXT,enabled_at INTEGER,PRIMARY KEY(domain,email));
CREATE TABLE account_totp_challenges(token TEXT PRIMARY KEY,domain TEXT,email TEXT,client_ip TEXT,return_path TEXT,created_at INTEGER,attempts INTEGER DEFAULT 0);
CREATE INDEX idx_analytics_events_domain_time ON analytics_events(domain,occurred_at);
CREATE INDEX idx_analytics_events_visitor ON analytics_events(domain,visitor_id,occurred_at);
CREATE INDEX idx_whole_site_imports_domain ON whole_site_imports(domain,state,updated_at);
CREATE INDEX idx_whole_site_import_pages_pending ON whole_site_import_pages(import_id,state,created_at);
CREATE INDEX idx_account_passkeys_user ON account_passkeys(domain,email);
CREATE INDEX idx_account_passkeys_handle ON account_passkeys(domain,user_handle);
PRAGMA user_version=9;
